<!--
 * 调度日历（下次触发时间查询）
 *
 * @path apps\cronjob-web\src\views\schedule-upcoming\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 调度日历（P1-下次触发时间查询）
 * <p>消费后端契约 scheduleCalendar.ts（auto-generated by bash/gen-contract.py）：
 * getUpcomingFireTimes 获取任务下次触发时间。
 * 布局：顶部筛选栏（任务标识 + 时间范围 + 最大条数）+ 触发时间列表 + 详情预览。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { YdBadge, YdButton, YdCard, YdCardContent, YdCardHeader, YdCardTitle, YdInput, YdEmptyState, YdTimeline, YdTimelineItem } from '@ydsz-core/ydsz-ui';
import { computed, ref } from 'vue';

import { getUpcomingFireTimes } from '#/api/scheduleCalendar';

import { createLogger } from '@ydsz-core/shared/utils';

const logger = createLogger('cronjob-schedule-upcoming');

defineOptions({ name: 'ScheduleUpcoming' });

// ==================== 数据 ====================

/** 任务标识筛选 */
const jobKey = ref<string>('');
/** 查询时间范围（小时） */
const hours = ref<number>(24);
/** 最大返回条数 */
const maxCount = ref<number>(50);
/** 触发时间列表 */
const fireTimes = ref<string[]>([]);
/** 加载状态 */
const isLoading = ref(false);

// ==================== 工具方法 ====================

/** 判断是否为近期触发（1 小时内） */
function isNearUpcoming(fireTime?: string): boolean {
  if (!fireTime) return false;
  const diff = new Date(fireTime).getTime() - Date.now();
  return diff > 0 && diff < 3600000;
}

/** 判断是否为今日触发 */
function isTodayUpcoming(fireTime?: string): boolean {
  if (!fireTime) return false;
  const now = new Date();
  const date = new Date(fireTime);
  return (
    date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate()
  );
}

/** 触发时间中文标签 */
function fireTimeTagType(fireTime?: string): 'danger' | 'warning' | 'info' {
  if (!fireTime) return 'info';
  if (isNearUpcoming(fireTime)) return 'danger';
  if (isTodayUpcoming(fireTime)) return 'warning';
  return 'info';
}

/** 触发时间显示标签 */
function fireTimeLabel(fireTime?: string): string {
  if (!fireTime) return '-';
  if (isNearUpcoming(fireTime)) return '即将触发';
  if (isTodayUpcoming(fireTime)) return '今日';
  return '未来';
}

/** 格式化触发时间显示 */
function formatFireTime(fireTime?: string): string {
  if (!fireTime) return '-';
  return fireTime.includes('T') ? fireTime.replace('T', ' ') : fireTime;
}

/** 计算倒计时文本 */
function getCountdown(fireTime?: string): string {
  if (!fireTime) return '';
  const diff = new Date(fireTime).getTime() - Date.now();
  if (diff <= 0) return '已触发';
  const hours2 = Math.floor(diff / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  const seconds = Math.floor((diff % 60000) / 1000);
  if (hours2 > 0) return `${hours2}h ${minutes}m ${seconds}s`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
}

// ==================== 计算属性 ====================

/** 时间线数据（带索引和标签） */
const timelineItems = computed(() => {
  return fireTimes.value.map((time, index) => ({
    index,
    time,
    label: fireTimeLabel(time),
    tagType: fireTimeTagType(time),
    countdown: getCountdown(time),
  }));
});

// ==================== 数据加载 ====================

/** 查询下次触发时间 */
async function handleQuery(): Promise<void> {
  if (!jobKey.value) {
    showToast.warning('请输入任务标识');
    return;
  }
  try {
    isLoading.value = true;
    const result = await getUpcomingFireTimes({
      jobKey: jobKey.value,
      hours: hours.value,
      maxCount: maxCount.value,
    });
    fireTimes.value = result ?? [];
    showToast.success(`查询到 ${fireTimes.value.length} 条触发时间`);
  } catch {
    logger.warn('查询触发时间失败', jobKey.value);
    fireTimes.value = [];
  } finally {
    isLoading.value = false;
  }
}

// ==================== Vxe 表格 ====================

interface FireTimeRow {
  index: number;
  fireTime: string;
  label: string;
  countdown: string;
}

const gridOptions: VxeTableGridOptions<FireTimeRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    {
      field: 'fireTime',
      title: '触发时间',
      width: 200,
      formatter: ({ cellValue }) => formatFireTime(cellValue),
    },
    {
      field: 'label',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) => {
          const item = row as FireTimeRow;
          const itemType = isNearUpcoming(item.fireTime)
            ? 'danger'
            : isTodayUpcoming(item.fireTime)
              ? 'warning'
              : 'info';
          return h(YdBadge, { size: 'sm', variant: itemType === 'info' ? 'secondary' : itemType }, () => item.label);
        },
      },
    },
    {
      field: 'countdown',
      title: '倒计时',
      width: 140,
      slots: {
        default: ({ row }) => {
          const item = row as FireTimeRow;
          const isNear = isNearUpcoming(item.fireTime);
          return h(
            'span',
            { class: isNear ? 'font-medium text-red-500' : 'text-gray-500' },
            item.countdown || '-',
          );
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }) => {
        if (!jobKey.value || fireTimes.value.length === 0) {
          return { items: [], total: 0 };
        }
        const allItems: FireTimeRow[] = fireTimes.value.map((time, index) => ({
          index,
          fireTime: time,
          label: fireTimeLabel(time),
          countdown: getCountdown(time),
        }));
        const start = (pageInfo.currentPage - 1) * pageInfo.pageSize;
        const end = start + pageInfo.pageSize;
        return { items: allItems.slice(start, end), total: allItems.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: false,
    items: [],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

/** 触发查询并刷新表格 */
async function handleSearch(): Promise<void> {
  await handleQuery();
  gridApi.query();
}

onMounted(() => {
  // 初始不查询，等待用户输入
});
</script>

<template>
  <Page auto-content-height>
    <!-- 筛选栏 -->
    <YdCard class="mb-3">
      <YdCardContent>
        <div class="flex flex-wrap items-center gap-3">
        <div class="flex items-center gap-2">
          <label class="whitespace-nowrap text-sm text-gray-600">任务标识：</label>
          <YdInput v-model="jobKey" placeholder="任务 Key" class="w-[180px]" />
        </div>
        <div class="flex items-center gap-2">
          <label class="whitespace-nowrap text-sm text-gray-600">时间范围：</label>
          <YdInput v-model="hours" type="number" :min="1" :max="168" class="w-24" />
          <span class="text-sm text-gray-400">小时</span>
        </div>
        <div class="flex items-center gap-2">
          <label class="whitespace-nowrap text-sm text-gray-600">最大条数：</label>
          <YdInput v-model="maxCount" type="number" :min="1" :max="500" class="w-24" />
        </div>
          <YdButton :loading="isLoading" @click="handleSearch">查询</YdButton>
        </div>
      </YdCardContent>
    </YdCard>

    <div class="grid grid-cols-1 gap-3 lg:grid-cols-5">
      <!-- 触发时间列表 -->
      <YdCard class="lg:col-span-3">
        <YdCardHeader>
          <YdCardTitle>下次触发时间列表 ({{ fireTimes.length }})</YdCardTitle>
        </YdCardHeader>
        <YdCardContent>
          <Grid table-title="" />
        </YdCardContent>
      </YdCard>

      <!-- 时间线预览 -->
      <YdCard class="lg:col-span-2">
        <YdCardHeader>
          <YdCardTitle>时间线预览</YdCardTitle>
        </YdCardHeader>
        <YdCardContent>
          <div v-if="timelineItems.length > 0" class="max-h-96 overflow-auto">
          <YdTimeline>
            <YdTimelineItem
              v-for="item in timelineItems.slice(0, 10)"
              :key="item.index"
              :timestamp="formatFireTime(item.time)"
              :type="item.tagType"
              placement="top"
            >
              <div class="flex items-center gap-2">
                <YdBadge size="sm" :variant="item.tagType === 'info' ? 'secondary' : item.tagType">{{ item.label }}</YdBadge>
                <span v-if="item.countdown" class="text-xs text-gray-500">{{ item.countdown }}</span>
              </div>
            </YdTimelineItem>
          </YdTimeline>
        </div>
          <YdEmptyState v-else description="暂无触发时间数据" :image-size="60" />
        </YdCardContent>
      </YdCard>
    </div>
  </Page>
</template>
